/* cppi::68600407bb73d73e52e148cabb64391af9195513bc79c0a5fe0235f247b8bc26 */
select cppib_sec_id, cppib_party_id, sedol, bloomberg_ticker_and_exchange, instrument_name FROM asset.asset_equity
where cppib_sec_id = 28975810 and business_date = DATE'2025-06-02'

/* cppi::66869ca26eec8c776d661645f65867aca3365c87e0363d05806d3f987fff00f1 */
/* QuickSight b09bf282-f3c1-44fe-9826-7dd13a3189c1 */
