/* cppi::f2da25e990838955f7f23f7a10767a778f7c3d852d9297676a126249ad23325c */
select id_isin as identifier, cppib_sec_id as ID_CPPIBSEC, ticker_exch_cd as ticker from asset.qsrp_security_equity_latest
     where id_isin is not null and cppib_sec_id is not null

/* cppi::30724e3a6efeb6e10e84adaf2acd99dfae0568c93a5104c67e2d0ee1c6c3cba0 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-12' and end_date = '2025-05-12')
and start_date = '2025-05-12' and end_date = '2025-05-12'

/* cppi::5c0dbb9085b51684fbb59c5acaae4bf4aab7832438cc6b9073b742eb511e43a8 */
SELECT "SUBCOL" AS "COL"
FROM (
  SELECT 1 AS "SUBCOL"
) "SUBQUERY"
GROUP BY 1

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
